const box = new Proxy({ pen: 1, ink: 2 }, {
  has(target, key) {
    return key !== "ink" && Reflect.has(target, key);
  },
  ownKeys(target) {
    return Reflect.ownKeys(target).filter((key) => key !== "pen");
  },
  deleteProperty() {
    return false;
  },
});

console.log("pen" in box, "ink" in box);
console.log(Object.keys(box).join(","));

try {
  delete box.pen;
} catch (error) {
  console.log(error.name);
}

console.log(box.pen + box.ink);
